<template>
  <template v-if="is_module_on">
    <f-btn
      v-if="is_f_btn"
      id="btn_tasks"
      @click="$emit('btnClicked')"
      class="q-mr-sm"
    >
      <Icon icon="mdi:clipboard-list" width="20" height="20" />
      <q-badge color="red" v-if="total_document_tasks > 0" rounded floating>{{
        total_document_tasks
      }}</q-badge>
      <q-tooltip>{{ $t('tasks') }}</q-tooltip>
    </f-btn>
    <q-btn
      v-else
      id="btn_tasks"
      class="cursor-pointer validation-view-button icon-grey"
      flat
      @click="$emit('btnClicked')"
    >
      <Icon icon="mdi:clipboard-check" width="20" height="20" />
      <q-badge color="red" v-if="total_document_tasks > 0" rounded floating>{{
        total_document_tasks
      }}</q-badge>
      <q-tooltip>{{ $t('tasks') }}</q-tooltip>
    </q-btn>
  </template>
</template>

<script lang="ts">

import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import {
  useTaskStore,
  useDocumentStore,
  useWebSocketStore,
  useSettingStore,
} from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { DeliveryCache } from 'src/constants';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  props: {
    is_f_btn: {
      type: Boolean,
      default: false,
    },
  },
    emits: ['btnClicked'],
  
  data() {
    return {
      taskClearInterval: 0 as any,
    };
  },
  watch: {
    doc_loaded: {
      handler: function (newVal, oldVal) {
        this.init();
      },
    },
    isConnected: {
      handler: function (newVal, oldVal) {
        this.use_websocket = true;
      },
    },
    websocketHasError: {
      handler: function (newVal, oldVal) {
        if (newVal == true) {
          this.use_websocket = false;
          this.handleWebsocketDelay();
        }
      },
    },
    tasks_data_flag: {
      handler: function (newVal, oldVal) {
        if (newVal == false) {
          return;
        }

        this.websocket_data_status = 'received';
        this.handleWebSocketResult(this.tasks_data);
      },
    },
    tasks_count: {
      handler: function (newVal, oldVal) {
        this.handleWsCountResult(newVal);
      },
    },
  },
  mounted: function () {
    this.init();
  },
  methods: {
    async init() {
      if (!(await this.isModuleOn())) {
        return;
      }

      this.fetchTasks();
      window.addEventListener('refresh_tasks', this.fetchTasksEvent);
    },
    unmounted: function () {
      window.removeEventListener('refresh_tasks', this.fetchTasksEvent);
    },

    tasksInterval(intervalFlag: boolean) {
      clearInterval(this.taskClearInterval);
      if (intervalFlag === true) {
        this.taskClearInterval = setInterval(() => {
          this.fetchTasks();
        }, 20000);
      }
    },

    fetchTasksEvent() {
      this.fetchTasks();
    },

    async fetchTasks() {
      try {
        if (!this.doc_loaded || !this.is_module_on || !this.record.doc_id) {
          return;
        }

        await this.startSettingsFetch();

        if (this.use_websocket) {
          // add wait for 5 second if there is till no response then switch to https
          this.terminateLongRunningTask(this.getTasksByWebsocket(), 5000).catch(() => {
            // Timeout handled internally by handleWebsocketDelay()
          });
          return;
        } else {
          await this.getOpenTasks(this.getDocumentId());
          setTimeout(this.turnOnWebSocket, 5000);
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    getDocumentId() {
      let document_id = '';
      if (this.record && this.record.doc_id) {
        document_id = this.record.doc_id;
      }

      return document_id;
    },

    prepareWsParams() {
      const params = this.prepareOpenTaskParams(this.getDocumentId());
      const default_params = this.makeDefaultParams(params);
      let cacheSetting =
        this.user_settings[DeliveryCache.get_task_and_notification_cache];
      if (cacheSetting) {
        cacheSetting = JSON.parse(
          this.user_settings[DeliveryCache.get_task_and_notification_cache],
        );
        if (cacheSetting.enabled) {
          params['cache'] = true;
          params['ttl'] = cacheSetting.ttl;
        }
      }
      Object.assign(params, default_params);
      return params;
    },

    async getTasksByWebsocket(): Promise<any> {
      try {
        const request = {
          type: 'tasks',
        } as dynamicObj;

        request['data'] = this.prepareWsParams();
        this.resetBeforeRequest(request['data']);
        this.websocket_data_status = 'fetching';
        this.tasks_data_flag = false;
        logInfo(request.type, request.data);
        const result = await this.sendMessageToSocket(
          request.type,
          request.data,
        );
        this.updateTaskData(result, request['data']);
        return true;
      } catch (err) {
        this.handleWebsocketDelay();
      } finally {
      }
    },

    turnOnWebSocket() {
      if (this.websocketHasError) {
        return;
      }

      this.use_websocket = true;
    },

    handleWebsocketDelay() {
      // websocket is still fetching data and we are not getting any response
      if (this.websocket_data_status === 'received') {
        return;
      }
      logInfo(
        'turning off websocket and switching to https',
        this.websocket_data_status,
      );
      this.use_websocket = false;
      this.fetchTasks();
      setTimeout(this.turnOnWebSocket, 5000);
    },

    terminateLongRunningTask(promise: any, ms: number) {
      return new Promise((resolve, reject) => {
        const timer = setTimeout(() => {
          reject(new Error('Operation timed out'));
          this.handleWebsocketDelay();
        }, ms);

        promise
          .then((result: any) => {
            clearTimeout(timer);
            resolve(result);
          })
          .catch((err: any) => {
            clearTimeout(timer);
            reject(err);
            this.handleWebsocketDelay();
          });
      });
    },

    handleWebSocketResult(data: dynamicObj) {
      if (!data) {
        return;
      }
      this.use_websocket = true;
      logInfo('websocket data received', data);
      const params = {
        document_id: '',
      };

      if (this.$route.fullPath.includes('/field_validation')) {
        if (this.$route.params.id === this.getDocumentId()) {
          params['document_id'] = this.$route.params.id;
        }
      }
      this.updateTaskData(data, params);
    },

    handleWsCountResult(data: any) {
      if (!data || data == 0) {
        return;
      }
      if (this.total_document_tasks == data) {
        return;
      }
      this.total_document_tasks = data;
      this.fetchTasks();
      const event = new CustomEvent('refresh_view', {});
      document.dispatchEvent(event);
    },
  },

  setup() {
    const websocket_store = useWebSocketStore();
    const {
      tasks_data,
      tasks_count,
      tasks_count_data_flag,
      isConnected,
      hasError: websocketHasError,
      tasks_data_flag,
    } = storeToRefs(websocket_store);
    const { sendMessageByType: sendMessageToSocket } = websocket_store;

    const task_store = useTaskStore();
    const {
      tasks,
      tasks_loading,
      total_records,
      total_document_tasks,
      is_module_on,
    } = storeToRefs(task_store);
    const {
      updateTaskData,
      getOpenTasks,
      isModuleOn,
      prepareOpenTaskParams,
      makeDefaultParams,
      resetBeforeRequest,
    } = task_store;

    const doc_store = useDocumentStore();
    const { record, doc_loaded } = storeToRefs(doc_store);

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    const { startSettingsFetch } = settings_store;

    return {
      tasks_data,
      isConnected,
      websocketHasError,
      tasks_data_flag,
      tasks_count,
      tasks_count_data_flag,
      sendMessageToSocket,
      use_websocket: ref(true),
      websocket_data_status: '',
      user_settings,
      startSettingsFetch,

      prepareOpenTaskParams,
      makeDefaultParams,
      resetBeforeRequest,
      updateTaskData,

      is_module_on,
      isModuleOn,

      doc_loaded,
      getOpenTasks,
      tasks,
      tasks_loading,
      total_records,
      total_document_tasks,
      record,
    };
  },
});
</script>

<style lang="scss" scoped></style>
